      if (previous.value?.resetEpochs?.[namespace] !== value.resetEpochs?.[namespace]) cacheQualifiedResetChoice(null);
      if (intent) pinInitialBootstrapIntent(intent, value);
      sharedBootstrapFailures.delete(config.url);
