    const expiresAt = Number.isFinite(Number(value.expiresAt))
      ? Number(value.expiresAt)
      : issuedAt + Math.max(1000, Number(value.lifetimeMs || NATIVE_BRANCH_CAPABILITY_DEFAULT_LIFETIME_MS) || NATIVE_BRANCH_CAPABILITY_DEFAULT_LIFETIME_MS);
