    const terms = termStats.slice(0, 96).map(row => row.term);
    const phrases = Array.from(phraseCounts.entries())
      .sort((a, b) => b[1] - a[1] || b[0].length - a[0].length || a[0].localeCompare(b[0]))
      .slice(0, FLASHBACK_MEMORY_LANE_PHRASE_LIMIT)
