            lexical: Number(row.weightedLexical.score.toFixed(4)),
            phrase: Number(row.phrase.score.toFixed(4)),
            anchor: Number(row.anchor.score.toFixed(4)),
            rareTerms: row.weightedLexical.rareMatched,
