      ...storedWorldline,
      revision: storedWorldline.revision + 1,
      liveHash: '',
      headTurnNodeId: nodes.filter(node => node.status === 'active').sort((a, b) => b.pairIndex - a.pairIndex)[0]?.turnNodeId || '',
