    const scope = scopeOverride?.scopeKey ? scopeOverride : scopeOverride ? { scopeKey: scopeOverride } : boundary.scope;
    const settings = settingsOverride || boundary.settings;
    const empty = { scopeKey: scope.scopeKey, reembedded: 0, embeddedVectors: 0, embeddedBatches: 0, physicalRequests: 0, selected: 0, pending: 0, skipped: true };
